CREATE POLICY ict_loan_photos_admin_delete_unused ON storage.objects FOR DELETE TO authenticated USING (bucket_id='ict-loan-photos' AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'director')) AND NOT EXISTS (SELECT 1 FROM public.ict_loans l WHERE split_part(split_part(l.borrow_photo_url,'/ict-loan-photos/',2),'?',1)=name OR split_part(split_part(l.return_photo_url,'/ict-loan-photos/',2),'?',1)=name));